// API Jinx UI принят по соглашению: Field/Input/Tag/Stack с пропами label, onRemove, gap — уточните имена по докам пакета.
import { useState, KeyboardEvent, ChangeEvent } from 'react';
import { Field, Input, Tag, Stack, Text } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
  maxTags?: number;
}

export default function ArticleTagPicker({
  value,
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  maxTags = 10,
}: ArticleTagPickerProps) {
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');
  const [error, setError] = useState<string | null>(null);

  const tags = value ?? internalTags;
  const isFull = tags.length >= maxTags;

  const commit = (next: string[]) => {
    if (value === undefined) setInternalTags(next);
    onChange?.(next);
  };

  const addTag = (raw: string) => {
    const tag = raw.trim().replace(/\s+/g, ' ');
    if (!tag) return;
    if (tags.some((t) => t.toLowerCase() === tag.toLowerCase())) {
      setError(`Тег «${tag}» уже добавлен`);
      return;
    }
    if (isFull) {
      setError(`Можно добавить не больше ${maxTags} тегов`);
      return;
    }
    setError(null);
    setDraft('');
    commit([...tags, tag]);
  };

  const removeTag = (tag: string) => {
    setError(null);
    commit(tags.filter((t) => t !== tag));
  };

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    const next = event.target.value;
    if (next.includes(',')) {
      next.split(',').forEach(addTag);
      return;
    }
    setError(null);
    setDraft(next);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag(draft);
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      removeTag(tags[tags.length - 1]);
    }
  };

  return (
    <Stack direction="column" gap="var(--jx-space-2)">
      <Field label={label} error={error ?? undefined}>
        <Input
          value={draft}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          onBlur={() => addTag(draft)}
          placeholder={isFull ? `Достигнут лимит в ${maxTags} тегов` : placeholder}
          disabled={isFull}
          aria-describedby="article-tag-picker-list"
        />
      </Field>

      {tags.length > 0 && (
        <Stack
          id="article-tag-picker-list"
          direction="row"
          wrap="wrap"
          gap="var(--jx-space-2)"
          role="list"
          aria-label="Выбранные теги"
        >
          {tags.map((tag) => (
            <Tag
              key={tag}
              role="listitem"
              onRemove={() => removeTag(tag)}
              removeLabel={`Удалить тег ${tag}`}
            >
              {tag}
            </Tag>
          ))}
        </Stack>
      )}

      <Text size="sm" tone="muted">
        {tags.length} из {maxTags} тегов
      </Text>
    </Stack>
  );
}

